CREATE TABLE integrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), provider varchar(50) NOT NULL, status varchar(20) NOT NULL DEFAULT 'connected', config jsonb NOT NULL DEFAULT '{}'::jsonb, connected_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT integrations_member_fk FOREIGN KEY(tenant_id,connected_by) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE api_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name varchar(120) NOT NULL, secret_hash varchar(128) NOT NULL, scopes jsonb NOT NULL, expires_at timestamptz, revoked_at timestamptz, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT api_clients_member_fk FOREIGN KEY(tenant_id,created_by) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), url varchar(500) NOT NULL, events jsonb NOT NULL, secret_hash varchar(128) NOT NULL, active boolean NOT NULL DEFAULT true, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT webhooks_member_fk FOREIGN KEY(tenant_id,created_by) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), webhook_id uuid NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE, event varchar(120) NOT NULL, status varchar(20) NOT NULL, attempts varchar(10) NOT NULL DEFAULT '0', response_code varchar(10), last_attempt_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
